/**
 * M14-2: the name data and its versions (design 6.3): the generated file names its Unicode version and NAME_DATA_VERSION (and is exactly what the
 * generator renders, its tables matching the SHA-256 in its header), the tables hold what the key needs and stay on the server (nothing the browser
 * contract imports reaches them), and two fixed data tables, the second making a colliding pair, give each name its old key under the first and its
 * new one under the second.
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { createNameData, createNameRules, CURRENT_NAME_DATA, encodeNameTable, PREVIOUS_NAME_DATA, type GeneratedNameData } from '@openmtg/accounts';
import { decodeNameTable } from '../../src/names/table';
import { tablesOf } from '../../src/names/data';
import { NAME_DATA_VERSION, TABLES_SHA256, UNICODE_DATA, UNICODE_VERSION } from '../../src/names/unicode-data';
import { PREVIOUS_UNICODE_DATA } from '../../src/names/unicode-data-prev';
import { renderModule } from '../../../../scripts/gen-unicode-data';

const file = (name: string) => readFileSync(fileURLToPath(new URL(`../../src/names/${name}`, import.meta.url)), 'utf8');
const src = fileURLToPath(new URL('../../src/', import.meta.url));

/** Every module specifier of a file (as test/m14-1/browser-safe.test.ts reads them): imports, exports, import(), require(). */
function specifiers(text: string): string[] {
  const out: string[] = [];
  for (const m of text.matchAll(/^\s*(?:import|export)\b[^;]*?\bfrom\s+['"]([^'"]+)['"]/gms)) out.push(m[1]!);
  for (const m of text.matchAll(/^\s*import\s+['"]([^'"]+)['"]/gm)) out.push(m[1]!);
  for (const m of text.matchAll(/\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g)) out.push(m[1]!);
  for (const m of text.matchAll(/\brequire\s*\(\s*['"]([^'"]+)['"]\s*\)/g)) out.push(m[1]!);
  return out;
}

/** The files of src/ reachable from api.ts and ./api/* through relative imports, type-only ones too (a bundler may keep a value import). */
function reachableFromApi(): string[] {
  const start = ['api.ts', ...readdirSync(join(src, 'api')).filter((f) => f.endsWith('.ts')).map((f) => `api/${f}`)].map((f) => join(src, f));
  const seen = new Set<string>();
  const todo = [...start];
  while (todo.length > 0) {
    const f = todo.pop()!;
    if (seen.has(f)) continue;
    seen.add(f);
    for (const sp of specifiers(readFileSync(f, 'utf8'))) {
      if (!sp.startsWith('./') && !sp.startsWith('../')) continue;
      const base = resolve(dirname(f), sp);
      const target = [`${base}.ts`, join(base, 'index.ts'), base].find((p) => {
        try {
          return readFileSync(p) !== undefined;
        } catch {
          return false;
        }
      });
      if (target !== undefined) todo.push(target);
    }
  }
  return [...seen].map((f) => relative(src, f).split('\\').join('/')).sort();
}

describe('M14-2: the generated name data', () => {
  it('names its Unicode version and NAME_DATA_VERSION, in its exports and its header', () => {
    expect(UNICODE_VERSION).toMatch(/^\d+\.\d+\.\d+$/);
    expect(UNICODE_VERSION).toBe('17.0.0');
    expect(Number.isSafeInteger(NAME_DATA_VERSION) && NAME_DATA_VERSION >= 1).toBe(true);
    expect(UNICODE_DATA.version).toBe(NAME_DATA_VERSION);
    expect(UNICODE_DATA.unicodeVersion).toBe(UNICODE_VERSION);
    expect(CURRENT_NAME_DATA).toEqual({ version: NAME_DATA_VERSION, unicodeVersion: UNICODE_VERSION });
    const text = file('unicode-data.ts');
    expect(text).toContain(`Unicode ${UNICODE_VERSION}, from CaseFolding-${UNICODE_VERSION}.txt`);
    expect(text).toContain(`confusables.txt (Version ${UNICODE_VERSION}`);
    expect(text).toContain(`NAME_DATA_VERSION ${NAME_DATA_VERSION}:`);
    expect(text).toContain('GENERATED by scripts/gen-unicode-data.ts');
    expect(text).toContain('Unicode License v3');
    // the "i" supplement is written into the header, and is the data's supplement table
    expect(text).toContain('OpenMTG supplement (not Unicode data), applied last in every round: "i" (U+0069) to "l" (U+006C)');
    expect(decodeNameTable(UNICODE_DATA.supplement)).toEqual(new Map([[0x69, 'l']]));
  });

  it('is exactly what the generator renders from its own data (no hand edits), and so is the previous-data file', () => {
    // the header's digest is of the tables as the generator wrote them: a hand edit of an entry changes the tables, not the digest
    const digest = createHash('sha256')
      .update(`${UNICODE_DATA.supplement}\n${UNICODE_DATA.overrides ?? ''}\n${UNICODE_DATA.caseFolding}\n${UNICODE_DATA.confusables}\n`, 'utf8').digest('hex');
    expect(digest).toBe(TABLES_SHA256);
    expect(file('unicode-data.ts')).toContain(`edit of a table shows: ${TABLES_SHA256}.`);
    expect(renderModule('current', UNICODE_DATA)).toBe(file('unicode-data.ts'));
    expect(renderModule('previous', PREVIOUS_UNICODE_DATA)).toBe(file('unicode-data-prev.ts'));
    expect(PREVIOUS_UNICODE_DATA).toBe(null);
    expect(PREVIOUS_NAME_DATA).toBe(null);
  });

  it('holds what the key needs: full case folding (C and F) and the confusable prototypes; it stays on the server', () => {
    const t = tablesOf(CURRENT_NAME_DATA);
    expect(t.caseFolding.get(0xdf)).toBe('ss'); // ß, status F
    expect(t.caseFolding.get(0x3a3)).toBe('σ'); // Σ
    expect(t.caseFolding.get(0x3c2)).toBe('σ'); // final sigma
    expect(t.caseFolding.get(0x130)).toBe('i\u0307'); // İ, status F (T is left out)
    expect(t.caseFolding.get(0x49)).toBe('i'); // I, status C (not the Turkic T)
    expect(t.confusables.get(0x49)).toBe('l');
    expect(t.confusables.get(0x31)).toBe('l');
    expect(t.confusables.get(0x30)).toBe('O');
    expect(t.confusables.get(0x6d)).toBe('rn');
    expect(t.confusables.get(0x430)).toBe('a'); // Cyrillic а
    expect(t.confusables.has(0x69)).toBe(false); // small "i" is its own prototype: hence the supplement
    expect(t.caseFolding.size).toBeGreaterThan(1_400);
    expect(t.confusables.size).toBeGreaterThan(6_000);
    // the derived table: Hebrew yod keeps itself (confusables.txt maps it to an apostrophe), Cyrillic EM keys like "M" (its fold is taken out)
    expect(decodeNameTable(UNICODE_DATA.confusables).get(0x5d9)).toBe("'");
    expect(t.confusables.get(0x5d9)).toBe('\u05d9');
    expect(t.caseFolding.has(0x41c)).toBe(false);
    expect(t.confusables.get(0x41c)).toBe('rn');
    expect(file('unicode-data.ts')).toContain("OpenMTG's derived table (not Unicode data)");
    expect(file('unicode-data.ts')).toContain('IdentifierStatus.txt (Version 17.0.0');
    expect(file('unicode-data.ts').length).toBeLessThan(150_000);
    // on the server only: nothing the browser contract (api.ts, ./api/*) imports, type-only imports included, is under src/names/
    const reached = reachableFromApi();
    for (const f of ['api.ts', 'api/names.ts', 'api/limits.ts']) expect(reached).toContain(f);
    expect(reached.filter((f) => f.startsWith('names/'))).toEqual([]);
  });
});

/** Two fixed data tables: ASCII case folding, a few prototypes; the second also maps "q" to "g", so "Qwen" and "Gwen" become one name. */
function fixedData(version: number, extra: [string, string][] = []): GeneratedNameData {
  const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  return {
    version,
    unicodeVersion: `test-${version}`,
    sources: 'fixed test tables',
    supplement: encodeNameTable([['i', 'l']]),
    caseFolding: encodeNameTable(Array.from(upper, (c) => [c, c.toLowerCase()] as [string, string])),
    confusables: encodeNameTable([['I', 'l'], ['1', 'l'], ['0', 'O'], ['m', 'rn'], ...extra]),
  };
}

describe('M14-2: name data versions (6.3)', () => {
  const v1 = createNameData(fixedData(1));
  const v2 = createNameData(fixedData(2, [['q', 'g']]));
  const under1 = createNameRules({ reservedNamesText: null, data: v1 });
  const switching = createNameRules({ reservedNamesText: null, data: v2, previous: v1 });

  it('each name keeps its old key under the first data and gets its new one under the second', () => {
    expect(under1.current).toBe(v1);
    expect(under1.previous).toBe(null);
    expect(switching.current).toBe(v2);
    expect(switching.previous).toBe(v1);
    for (const n of ['Qwen', 'Gwen', 'Quinn', 'Alice', 'MIKE', 'B0b']) {
      expect(switching.key(n, v1), n).toBe(under1.key(n));
      expect(switching.key(n, v2), n).toBe(switching.key(n));
    }
    expect(switching.key('Qwen', v1)).toBe('qwen');
    expect(switching.key('Qwen')).toBe('gwen');
  });

  it('the second data makes a colliding pair the first keeps apart', () => {
    expect(under1.key('Qwen')).not.toBe(under1.key('Gwen'));
    expect(switching.key('Qwen', v1)).not.toBe(switching.key('Gwen', v1));
    expect(switching.key('Qwen')).toBe(switching.key('Gwen'));
    // names the new mapping does not touch keep their key across the versions
    for (const n of ['Alice', 'MIKE', 'B0b']) expect(switching.key(n, v1)).toBe(switching.key(n, v2));
  });

  it('during the switch a reserved word is keyed under both versions', () => {
    const r = createNameRules({ reservedNamesText: 'Gwen\n', data: v2, previous: v1 });
    expect(r.reservedProblem(r.key('Qwen'))).toBe('reserved'); // "gwen" under v2
    expect(r.reservedProblem(r.key('Gwen', v1))).toBe('reserved');
    expect(r.reservedProblem(r.key('Qwen', v1))).toBe(null); // "qwen" under v1 is no reserved key of either version
  });

  it('refuses a previous version equal to the current one, and data it did not build', () => {
    expect(() => createNameRules({ reservedNamesText: null, data: v1, previous: createNameData(fixedData(1)) })).toThrow(/previous name data has the current version/);
    expect(() => createNameRules({ reservedNamesText: null, data: { version: 3, unicodeVersion: 'x' } })).toThrow(/unknown name data/);
    expect(() => createNameData({ ...fixedData(1), version: 0 })).toThrow(/positive integer/);
  });

  it('defaults: the generated data, and its previous data (none in this release)', () => {
    const r = createNameRules({ reservedNamesText: null });
    expect(r.current).toBe(CURRENT_NAME_DATA);
    expect(r.previous).toBe(PREVIOUS_NAME_DATA);
  });
});

describe('M14-2: the table format', () => {
  it('round-trips, sorted by source, and refuses malformed lines, repeated sources and sources of more than one code point', () => {
    const text = encodeNameTable([['ß', 'ss'], ['A', 'a'], ['𝐀', 'A']]);
    expect(text).toBe('41>61\ndf>73 73\n1d400>41');
    expect(decodeNameTable(text)).toEqual(new Map([[0x41, 'a'], [0xdf, 'ss'], [0x1d400, 'A']]));
    expect(decodeNameTable('')).toEqual(new Map());
    for (const bad of ['41>', '>61', '41 61', 'zz>61', '41>61\n41>62', '110000>41']) expect(() => decodeNameTable(bad), bad).toThrow();
    expect(() => encodeNameTable([['ab', 'c']])).toThrow(/one code point/);
    expect(() => encodeNameTable([['a', '']])).toThrow(/empty/);
  });
});
